import math
import numpy as np
from scipy.optimize import least_squares

_PARAMS = None

def _value(row, p):
    vmax, rho, c_loc = p
    u = max(1e-8, float(row['u_now']))
    g = max(0.0, float(row['s_grad']))
    return vmax * (1.0 - rho * g / (1.0 + g)) * (u / (1.2 + u)) + c_loc * math.sqrt(u)

def fit(train_rows):
    global _PARAMS
    ys = np.asarray([float(r['y']) for r in train_rows])
    def residual(p):
        return np.asarray([_value(r, p) for r in train_rows]) - ys
    result = least_squares(residual, x0=np.array([3.0, 0.7, 0.2]), bounds=([0.0, 0.0, -5.0], [20.0, 1.5, 5.0]), max_nfev=20000)
    _PARAMS = result.x
    return result.x

def predict(row) -> float:
    if _PARAMS is None:
        raise RuntimeError('fit(train_rows) must be called before predict(row)')
    return float(_value(row, _PARAMS))
